<div class="d-flex justify-content-between align-items-center mb-4"><h1>📦 Productos</h1><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#modalProducto"><i class="bi bi-plus-lg"></i> Nuevo Producto</button></div>
<div class="card"><div class="card-body table-responsive"><table class="table table-hover align-middle"><thead class="table-light"><tr><th>ID</th><th>Nombre</th><th>Stock</th><th>Precio</th><th>Acciones</th></tr></thead><tbody>
<?php foreach ($productos as $p): ?><tr><td><?= (int)$p['ID_Producto'] ?></td><td><?= htmlspecialchars($p['Nombre'],ENT_QUOTES,'UTF-8') ?></td><td><span class="badge bg-<?= $p['Stock']<5?'danger':'success' ?>"><?= (int)$p['Stock'] ?></span></td><td>S/<?= number_format((float)$p['Precio'],2) ?></td><td class="text-nowrap">
<button class="btn btn-sm btn-outline-primary btn-editar-producto" data-bs-toggle="modal" data-bs-target="#modalEditarProducto" data-id="<?= (int)$p['ID_Producto'] ?>" data-nombre="<?= htmlspecialchars($p['Nombre'],ENT_QUOTES,'UTF-8') ?>" data-stock="<?= (int)$p['Stock'] ?>" data-precio="<?= htmlspecialchars((string)$p['Precio'],ENT_QUOTES,'UTF-8') ?>"><i class="bi bi-pencil"></i> Actualizar</button>
<form class="d-inline" method="post" action="index.php?controller=producto&action=eliminar" onsubmit="return confirm('¿Eliminar este producto? Solo será posible si no tiene movimientos asociados.')"><input type="hidden" name="id" value="<?= (int)$p['ID_Producto'] ?>"><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i> Eliminar</button></form></td></tr><?php endforeach; ?>
<?php if (!$productos): ?><tr><td colspan="5" class="text-center text-muted">No hay productos registrados.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="modal fade" id="modalProducto" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><form method="POST" action="index.php?controller=producto&action=crear" class="modal-content"><div class="modal-header"><h5 class="modal-title">Nuevo Producto</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="mb-3"><label class="form-label">Nombre</label><input type="text" name="Nombre" class="form-control" required maxlength="50"></div><div class="mb-3"><label class="form-label">Stock inicial</label><input type="number" name="Stock" class="form-control" min="0" value="0" required></div><div class="mb-3"><label class="form-label">Precio</label><input type="number" name="Precio" class="form-control" step="0.01" min="0" required></div></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button><button type="submit" class="btn btn-primary">Guardar</button></div></form></div></div>
<div class="modal fade" id="modalEditarProducto" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><form method="POST" action="index.php?controller=producto&action=actualizar" class="modal-content"><div class="modal-header"><h5 class="modal-title">Actualizar producto</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="ID_Producto" id="editProdId"><div class="mb-3"><label class="form-label">Nombre</label><input class="form-control" name="Nombre" id="editProdNombre" maxlength="50" required></div><div class="mb-3"><label class="form-label">Stock</label><input class="form-control" type="number" name="Stock" id="editProdStock" min="0" required></div><div class="mb-3"><label class="form-label">Precio</label><input class="form-control" type="number" step="0.01" min="0" name="Precio" id="editProdPrecio" required></div></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Guardar cambios</button></div></form></div></div>
<script>document.querySelectorAll('.btn-editar-producto').forEach(b=>b.addEventListener('click',function(){document.getElementById('editProdId').value=this.dataset.id;document.getElementById('editProdNombre').value=this.dataset.nombre;document.getElementById('editProdStock').value=this.dataset.stock;document.getElementById('editProdPrecio').value=this.dataset.precio;}));</script>
